import 'package:flutter_riverpod/flutter_riverpod.dart';
import 'package:material_ui/material_ui.dart';

import '../../../../core/theme/app_colors.dart';
import '../../application/recipe_providers.dart';
import '../../domain/recipe.dart';
import 'recipe_illustration.dart';

/// The picture of a recipe, generated by AI (PRD §6.3). Shows
/// [RecipeIllustration] while there is none: loading, offline, out of quota or
/// failed.
class RecipePicture extends ConsumerWidget {
  const RecipePicture({
    super.key,
    required this.recipe,
    this.height = 160,
    this.borderRadius = BorderRadius.zero,
  });

  final Recipe recipe;
  final double height;
  final BorderRadius borderRadius;

  @override
  Widget build(BuildContext context, WidgetRef ref) {
    final image = ref.watch(recipeImageProvider(imageQueryFor(recipe))).value;
    final fallback = RecipeIllustration(
      illustrationKey: recipe.illustrationKey,
      height: height,
      borderRadius: borderRadius,
    );
    if (image == null) return fallback;
    return ClipRRect(
      borderRadius: borderRadius,
      child: Image.file(
        image,
        height: height,
        width: double.infinity,
        fit: BoxFit.cover,
        semanticLabel: 'AI-generated picture of ${recipe.name}',
        errorBuilder: (_, _, _) => fallback,
      ),
    );
  }
}

/// Says that the picture was made by AI; empty when no picture is shown.
class RecipeImageNote extends ConsumerWidget {
  const RecipeImageNote({super.key, required this.recipe});

  static const text = 'Picture generated by AI. Your dish may look different.';

  final Recipe recipe;

  @override
  Widget build(BuildContext context, WidgetRef ref) {
    final image = ref.watch(recipeImageProvider(imageQueryFor(recipe))).value;
    if (image == null) return const SizedBox.shrink();
    return const Padding(
      padding: EdgeInsets.only(top: 8),
      child: Text(
        text,
        style: TextStyle(fontSize: 11, color: AppColors.textSecondary),
      ),
    );
  }
}
